import { KeyValueEditor, Card } from "march/ui"

// kek tarifi: malzeme → gram; sayılar sayı olarak saklanır, toplam hamur ağırlığı canlı hesaplanır
export function CakeRecipe() {
  let $recipe: Record<string, string | number> = { "un": 250, "şeker": 180, "tereyağı": 120, "yumurta": 150 }
  const $total = Object.values($recipe).reduce((sum: number, g) => sum + (typeof g === "number" ? g : 0), 0)
  return <Card title="Limonlu kek" subtitle={`Toplam hamur: ${$total} g`}>
    <KeyValueEditor bind:value={$recipe} numbers keyPlaceholder="Malzeme" valuePlaceholder="Gram"
      labels={{ key: "Malzeme", value: "Gram", remove: "Malzemeyi çıkar", add: "Malzeme ekle", duplicate: "Bu malzeme zaten var" }} />
    <span sx={{ text: "sm", color: "muted" }}>{$total > 800 ? "Büyük kalıp gerekecek." : "Orta boy kalıba sığar."}</span>
  </Card>
}

import { KeyValueEditor, Field, Button, Card, toast } from "march/ui"
import { save } from "march/icons"

// yayın ayarları: uygulamanın ortam değişkenleri; altta .env dosyasının önizlemesi, kaydedince yeni sürüm çıkar
export function EnvSettings() {
  let $env: Record<string, string | number> = { API_URL: "https://api.hadisosyal.com", CACHE_TTL: "3600", LOG_LEVEL: "warn" }
  let $saving = false
  const $file = Object.entries($env).map(([k, v]) => `${k}=${v}`).join("\n")
  const deploy = () => {
    $saving = true
    setTimeout(() => { $saving = false; toast(`${Object.keys($env).length} değişkenle yeni sürüm yayında`) }, 1000)
  }
  return <Card title="Ortam değişkenleri" subtitle="Üretim · hadi-web"
    footer={<Button variant="primary" icon={save} loading={$saving} on:click={deploy}>Kaydet ve yayınla</Button>}>
    <Field label="Değişkenler" group help="Aynı ad iki kez yazılırsa yalnız ilki kaydedilir.">
      <KeyValueEditor bind:value={$env} keyPlaceholder="DEĞİŞKEN_ADI" valuePlaceholder="değer"
        labels={{ key: "Değişken adı", value: "Değeri", remove: "Değişkeni sil", add: "Değişken ekle", duplicate: "Bu ad zaten tanımlı" }} />
    </Field>
    <pre sx={{ text: ["sm", "mono"], p: 2, radius: 2 }}>{$file}</pre>
  </Card>
}

import { KeyValueEditor } from "march/ui"
import { trash } from "march/icons"

// KeyValueEditor'un bütün özellikleri bir arada: bağlı değer (bind:value) ve onChange, sayılar (numbers),
// yer tutucular (keyPlaceholder, valuePlaceholder), metinler (labels: key, value, remove, add, duplicate),
// kendi kaldırma ikonun (removeIcon), kaldırma / ekleme kapatma (removable, addable), salt okunur, devre dışı,
// labelledby, odak kaybı (onBlur), id ve sınıf
const Section = (props: { title: string; children?: unknown }) => <div sx={{ flex: "col", gap: 1 }}>
  <span sx={{ text: "xs", color: "muted" }}>{props.title}</span>
  {props.children}
</div>

export function KeyValueEditorLab() {
  let $plans: Record<string, string | number> = { free: 1, team: 10 }
  let $headers: Record<string, string | number> = { Accept: "application/json" }
  let $changes = 0
  let $blurs = 0
  return <div sx={{ flex: "col", gap: 4 }}>
    <Section title="Sayılar, kendi metinleri ve ikonu, onChange">
      <span id="lab-plans">Plan kotaları</span>
      <KeyValueEditor bind:value={$plans} numbers onChange={() => $changes++} onBlur={() => $blurs++}
        id="lab-plan-key" class="lab-plans" labelledby="lab-plans" keyPlaceholder="ör. pro" valuePlaceholder="ör. 25"
        labels={{ key: "Plan", value: "Koltuk", remove: "Planı sil", add: "Plan ekle", duplicate: "Bu plan zaten var" }}
        removeIcon={trash} />
      <pre>Kota: {JSON.stringify($plans)}</pre>
      <span sx={{ text: "sm", color: "muted" }}>Değişiklik: {$changes} · odak kaybı: {$blurs}</span>
    </Section>
    <Section title="Metin olarak (numbers yok), kaldırma düğmesi yok">
      <KeyValueEditor bind:value={$headers} removable={false} labels={{ key: "Başlık", value: "Başlık değeri", add: "Başlık ekle" }} />
      <pre>Başlıklar: {JSON.stringify($headers)}</pre>
    </Section>
    <Section title="Ekleme yok (addable={false}), salt okunur, devre dışı">
      <KeyValueEditor value={{ "renk": "mavi" }} addable={false} labels={{ key: "Sabit anahtar", value: "Sabit değer" }} />
      <KeyValueEditor value={{ "sürüm": "0.2.0" }} readonly labels={{ key: "Salt okunur anahtar", value: "Salt okunur değer" }} />
      <KeyValueEditor value={{ "bölge": "eu" }} disabled labels={{ key: "Kilitli anahtar", value: "Kilitli değer" }} />
    </Section>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { KeyValueEditorLab } from "./KeyValueEditorLab.tsx"

// KeyValueEditorLab'in testleri: kaydedince Testler sekmesinde çalışır
test("numbers ile yazılan değer sayı olur, onChange sayar", async () => {
  const s = renderTest(() => <KeyValueEditorLab />)
  await s.type("Koltuk", "3")
  expect(s.text().includes('Kota: {"free":3,"team":10}')).toBe(true)
  expect(s.text().includes("Değişiklik: 1")).toBe(true)
})

test("Plan ekle yeni bir satır açar; ad ve değer yazılınca nesneye girer", async () => {
  const s = renderTest(() => <KeyValueEditorLab />)
  await s.click("Plan ekle")
  const keys = s.all('input[aria-label="Plan"]')
  expect(keys.length).toBe(3)
  await s.type(keys[2]!, "pro")
  await s.type(s.all('input[aria-label="Koltuk"]')[2]!, "25")
  expect(s.text().includes('Kota: {"free":1,"team":10,"pro":25}')).toBe(true)
})

test("yinelenen anahtar işaretlenir ve nesneye girmez", async () => {
  const s = renderTest(() => <KeyValueEditorLab />)
  const second = await s.type(s.all('input[aria-label="Plan"]')[1]!, "free")
  expect(s.text().includes("Bu plan zaten var")).toBe(true)
  expect(second.getAttribute("aria-invalid")).toBe("true")
  expect(s.text().includes('Kota: {"free":1}')).toBe(true)
})

test("Planı sil satırı kaldırır; numbers olmadan değer metin kalır; salt okunurda düğme yok", async () => {
  const s = renderTest(() => <KeyValueEditorLab />)
  await s.click("Planı sil")
  expect(s.text().includes('Kota: {"team":10}')).toBe(true)
  await s.type("Başlık değeri", "100")
  expect(s.text().includes('Başlıklar: {"Accept":"100"}')).toBe(true)
  expect(s.find("Salt okunur anahtar")?.hasAttribute("readonly")).toBe(true)
  expect(s.get(".lab-plans")?.getAttribute("aria-labelledby")).toBe("lab-plans")
})
